let ai = null;
try {
  const raw = $json.output[0].content[0].text;
  ai = (typeof raw === 'string') ? JSON.parse(raw) : raw;
} catch (e) { ai = null; }

const row = $("Get New Strong Rows").item.json;
const hasContact = String(row.contact_email || '').trim() !== '' || String(row.contact_phone || '').trim() !== '';

if (!ai) {
  return { json: { source_id: row.source_id, skip: true } };
}

let outreach = ai.outreach_draft || '';
if (!hasContact) {
  outreach = "No verified contact available - no outreach drafted.";
}

return { json: {
  source_id: row.source_id,
  skip: false,
  resume_content: ai.resume_content || '',
  cover_letter: ai.cover_letter || '',
  linkedin_headline: ai.linkedin_headline || '',
  linkedin_about: ai.linkedin_about || '',
  recruiter_keywords: ai.recruiter_keywords || '',
  interview_prep: ai.interview_prep || '',
  outreach_draft: outreach,
} };

const LF = String.fromCharCode(10);
const all = $input.all().map(function (i) { return i.json; });
const rows = all.filter(function (r) {
  return r && (r.job_status === 'new' || r.job_status === 'prepped') && r.company_name;
});
rows.sort(function (a, b) {
  const pa = Number(a.priority_rank) || 99;
  const pb = Number(b.priority_rank) || 99;
  if (pa !== pb) return pa - pb;
  return (Number(b.match_score) || 0) - (Number(a.match_score) || 0);
});
const top = rows.slice(0, 15);
function nv(v) { return (v !== undefined && v !== null && String(v).trim() !== '') ? String(v) : 'not verified'; }
function esc(v) { return String(v === undefined || v === null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

const parts = [];
parts.push('<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">');
parts.push('<p style="background:#fff3cd;border:1px solid #ffe69c;padding:10px;border-radius:6px"><strong>DRAFTS ONLY - nothing has been sent to any recruiter. Reply to approve any outreach.</strong></p>');

if (top.length === 0) {
  parts.push('<p>No new matching pharma QA jobs today. Your monitors are still running.</p>');
} else {
  parts.push('<p>Top ' + top.length + ' pharma QA opportunities (walk-ins first, then direct, then upcoming):</p>');
  for (let k = 0; k < top.length; k++) {
    const j = top[k];
    parts.push('<div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin-bottom:12px">');
    parts.push('<h3 style="margin:0 0 6px">' + (k + 1) + '. ' + esc(j.company_name) + ' - ' + esc(j.job_title) + '</h3>');
    parts.push('<p style="margin:2px 0"><strong>Match score:</strong> ' + (Number(j.match_score) || 0) + '/100 &nbsp; | &nbsp; <strong>Type:</strong> ' + esc(j.opportunity_type || '') + ' &nbsp; | &nbsp; <strong>Verification:</strong> ' + esc(j.verification_status || 'not verified') + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Department:</strong> ' + esc(nv(j.department)) + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Location:</strong> ' + esc(nv(j.location)) + ' &nbsp; <strong>Address:</strong> ' + esc(nv(j.address)) + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Walk-in:</strong> ' + esc(nv(j.walkin_datetime)) + ' &nbsp; <strong>Venue:</strong> ' + esc(nv(j.walkin_venue)) + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Experience:</strong> ' + esc(nv(j.experience_required)) + ' &nbsp; <strong>Salary/CTC:</strong> ' + esc(nv(j.salary_ctc)) + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Company:</strong> ' + esc(nv(j.company_size_type)) + '</p>');
    parts.push('<p style="margin:2px 0"><strong>Email:</strong> ' + esc(nv(j.contact_email)) + ' &nbsp; <strong>Phone:</strong> ' + esc(nv(j.contact_phone)) + ' &nbsp; <strong>WhatsApp:</strong> ' + esc(nv(j.contact_whatsapp)) + '</p>');
    const link = (j.apply_link && String(j.apply_link).trim() !== '') ? ('<a href="' + esc(j.apply_link) + '">' + esc(j.apply_link) + '</a>') : 'not verified';
    parts.push('<p style="margin:2px 0"><strong>Apply:</strong> ' + link + '</p>');
    if (j.job_status === 'prepped') {
      parts.push('<p style="margin:6px 0 0;color:#0a6">Resume, cover letter, LinkedIn content, keywords, interview prep and an outreach draft are ready in your tracker for approval.</p>');
    }
    parts.push('</div>');
  }
}
parts.push('</div>');

const html = parts.join(LF);
const subject = 'Pharma QA Job Digest - ' + top.length + ' matches (' + ($now.toFormat('dd LLL yyyy')) + ')';
return [{ json: { subject: subject, html: html, count: top.length } }];
